<script setup lang="ts">
// Settings → About → Licences (M5 Task 12): every component a release ships,
// with its licence, the same list as THIRD-PARTY.md (both generated by
// lab/release/third-party.mjs). The list is loaded only when asked for.
import { computed, ref } from "vue";
import { useI18n } from "vue-i18n";

type Component = { name: string; version: string; licence: string; kind: "modem" | "installer" | "rust" | "npm"; url: string };
const KINDS = ["modem", "installer", "rust", "npm"] as const;

const { t } = useI18n();
const list = ref<Component[] | null>(null);
const query = ref("");

async function show() {
  list.value = (await import("../thirdParty.json")).default as Component[];
}
const shown = computed(() => {
  const q = query.value.trim().toLowerCase();
  const all = list.value ?? [];
  return q ? all.filter((c) => c.name.toLowerCase().includes(q) || c.licence.toLowerCase().includes(q)) : all;
});
const byKind = (k: (typeof KINDS)[number]) => shown.value.filter((c) => c.kind === k);
</script>

<template>
  <section class="card stack licences" aria-labelledby="h-licences">
    <h2 id="h-licences">{{ t("licences.title") }}</h2>
    <p class="small">{{ t("licences.body") }}</p>
    <div v-if="!list"><button class="licences-show" @click="show">{{ t("licences.show") }}</button></div>
    <template v-else>
      <input v-model="query" class="licences-search" type="search" :aria-label="t('licences.search')" :placeholder="t('licences.search')" />
      <p class="muted small licences-count">{{ t("licences.count", { n: shown.length }) }}</p>
      <template v-for="k in KINDS" :key="k">
        <div v-if="byKind(k).length" class="table-wrap">
          <table class="small">
            <caption class="label">{{ t(`licences.kind.${k}`) }}</caption>
            <thead>
              <tr><th scope="col">{{ t("licences.component") }}</th><th scope="col">{{ t("licences.version") }}</th><th scope="col">{{ t("licences.licence") }}</th></tr>
            </thead>
            <tbody>
              <tr v-for="c in byKind(k)" :key="c.name + c.version" :data-component="c.name">
                <td class="mono">{{ c.name }}</td><td class="mono">{{ c.version }}</td><td>{{ c.licence }}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </template>
    </template>
  </section>
</template>

<style scoped>
.table-wrap { overflow-x: auto; position: relative; max-height: 320px; overflow-y: auto; }
table { width: 100%; border-collapse: collapse; }
caption { text-align: left; padding: 6px 0; }
th, td { text-align: left; padding: 3px 8px 3px 0; border-bottom: 1px solid var(--border); overflow-wrap: anywhere; }
.licences-search { width: 100%; }
</style>
